"use client";

import { forwardRef, useMemo, type ClipboardEvent, type HTMLAttributes } from "react";
import { cn } from "@/lib/cn";
import { sanitizeRichText, type RichTextFormatting } from "@/lib/rich-text";

/**
 * How stored rich text reads. Exported so an app can put the same classes on a
 * `RichTextEditor` and have a document look the same being written as it does
 * being read. Semantic tokens only, so it holds in both themes.
 *
 * Images are block-level, never wider than the text and centered by default.
 * An image with a `data-align` carries an inline style generated by the
 * sanitizer (`imageAlignmentAttributes`), which wins over the centering here.
 */
export const RICH_TEXT_PROSE = [
  "[&_a]:text-accent-text [&_a]:underline [&_a]:underline-offset-2",
  "[&_ol]:my-1 [&_ol]:list-decimal [&_ol]:pl-5",
  "[&_ul]:my-1 [&_ul]:list-disc [&_ul]:pl-5",
  "[&_li]:my-0.5",
  "[&_p]:my-1 [&_p:first-child]:mt-0 [&_p:last-child]:mb-0",
  "[&_strong]:font-semibold [&_strong]:text-text-primary [&_s]:line-through",
  "[&_h1]:mt-3 [&_h1]:mb-1 [&_h1]:text-2xl [&_h1]:font-semibold [&_h1]:text-accent-text [&_h1:first-child]:mt-0",
  "[&_h2]:mt-3 [&_h2]:mb-1 [&_h2]:text-xl [&_h2]:font-semibold [&_h2]:text-info-text [&_h2:first-child]:mt-0",
  "[&_h3]:mt-2 [&_h3]:mb-1 [&_h3]:text-lg [&_h3]:font-semibold [&_h3]:text-text-primary [&_h3:first-child]:mt-0",
  "[&_h1_strong]:text-inherit [&_h2_strong]:text-inherit [&_h3_strong]:text-inherit",
  "[&_blockquote]:my-2 [&_blockquote]:border-l-[3px] [&_blockquote]:border-accent [&_blockquote]:pl-3 [&_blockquote]:text-text-secondary",
  "[&_code]:rounded-sm [&_code]:bg-surface-overlay [&_code]:px-1 [&_code]:py-px [&_code]:font-mono [&_code]:text-[0.8125rem] [&_code]:text-accent-text",
  "[&_pre]:my-2 [&_pre]:overflow-x-auto [&_pre]:whitespace-pre [&_pre]:rounded-md [&_pre]:border [&_pre]:border-border-subtle [&_pre]:bg-surface-overlay [&_pre]:px-3 [&_pre]:py-2 [&_pre]:font-mono [&_pre]:text-[0.8125rem] [&_pre]:leading-relaxed",
  "[&_pre_code]:bg-transparent [&_pre_code]:p-0 [&_pre_code]:text-text-primary",
  "[&_img]:block [&_img]:mx-auto [&_img]:max-w-full [&_img]:h-auto",
].join(" ");

export interface RichTextViewProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "children" | "dangerouslySetInnerHTML" | "onCopy"> {
  /** Stored rich text. Sanitized here, every render, with the options below. */
  html: string;
  /** The editor configuration that wrote it. Default `extended`. */
  formatting?: RichTextFormatting;
  /** Keep images. Default `true`. */
  images?: boolean;
  /**
   * Copy a selection inside the document as its sanitized HTML, with absolute
   * image and link URLs, instead of the browser's computed styles. Pasting into
   * an email then carries the document's formatting and image alignment, not
   * the page's light or dark theme. Selections that leave the document copy
   * as the browser normally does.
   */
  cleanCopy?: boolean;
  /**
   * Runs on the sanitized markup before it renders. Whatever it returns is
   * rendered as is, so use it only to restore what you replaced before
   * sanitizing — a relative app link swapped for a placeholder, say.
   */
  transform?: (sanitized: string) => string;
}

/**
 * Read-only stored rich text: the counterpart of `RichTextEditor`. Sanitizes
 * `html` itself (`sanitizeRichText` is idempotent, so markup an app already
 * cleaned on the server comes through unchanged), styles it with
 * `RICH_TEXT_PROSE`, and is a `flow-root` so an image wrapped with text
 * (`data-align="left-wrap"`) never spills past the end of the document.
 *
 * Size and colour of the body text are the caller's, through `className`.
 */
export const RichTextView = forwardRef<HTMLDivElement, RichTextViewProps>(
  ({ html, formatting = "extended", images = true, cleanCopy = false, transform, className, ...props }, ref) => {
    const clean = useMemo(() => {
      const sanitized = sanitizeRichText(html, { formatting, images });
      return transform ? transform(sanitized) : sanitized;
    }, [html, formatting, images, transform]);

    function copy(event: ClipboardEvent<HTMLDivElement>) {
      const selection = window.getSelection();
      if (
        selection?.rangeCount !== 1 ||
        selection.isCollapsed ||
        !event.currentTarget.contains(selection.anchorNode) ||
        !event.currentTarget.contains(selection.focusNode)
      )
        return;
      const fragment = document.createElement("div");
      fragment.append(selection.getRangeAt(0).cloneContents());
      // Clipboard HTML is opened at the destination's origin, not this page's.
      for (const image of fragment.querySelectorAll<HTMLImageElement>("img[src]")) image.setAttribute("src", image.src);
      for (const link of fragment.querySelectorAll<HTMLAnchorElement>("a[href]")) link.setAttribute("href", link.href);
      event.clipboardData.setData("text/html", sanitizeRichText(fragment.innerHTML, { formatting, images }));
      event.clipboardData.setData("text/plain", selection.toString());
      event.preventDefault();
    }

    return (
      <div
        ref={ref}
        {...props}
        className={cn("flow-root", RICH_TEXT_PROSE, className)}
        onCopy={cleanCopy ? copy : undefined}
        dangerouslySetInnerHTML={{ __html: clean }}
      />
    );
  },
);
RichTextView.displayName = "RichTextView";
